/**
 * WorldConfigurationValidator strictly validates candidate world configurations
 * generated by AI or user inputs before allowing execution or database persistence.
 *
 * Enforces rules on:
 * - Population (bounds [100, 1,000,000])
 * - City Counts (bounds [1, 50])
 * - Resource Reserves (non-negative numbers, reasonable floors)
 * - Required Fields (name, biome, governmentType, startingMoney)
 * - Range and Type Checks
 */
export class WorldConfigurationValidator {
  static RULES = {
    POPULATION: { min: 100, max: 1000000, default: 5000 },
    CITIES_COUNT: { min: 1, max: 50, default: 2 },
    STARTING_MONEY: { min: 1000, max: 100000000, default: 500000 },
    TAX_RATE: { min: 0.01, max: 0.50, default: 0.15 },
    RESOURCE_MIN: 0,
    RESOURCE_MAX: 1000000,
    DEFAULT_RESOURCES: {
      water: 5000,
      energy: 5000,
      agriculture: 3000,
      minerals: 2500,
      technology: 1000,
    },
    GOVERNMENT_TYPES: [
      'Central Government',
      'Technocracy',
      'Democracy',
      'Direct Democracy',
      'Republic',
      'Council Federation',
      'Monarchy',
      'Algorithmic Syndicate',
    ],
    BIOMES: [
      'Desert',
      'Arid Wasteland',
      'Cybernetic Basin',
      'Temperate Plains',
      'Coastal Delta',
      'Mountain Highlands',
      'Tropical Rainforest',
      'Tundra / Polar',
    ],
  };

  /**
   * Validate and sanitize candidate configuration
   * @param {Object} rawConfig
   * @returns {{ valid: boolean, errors: string[], warnings: string[], sanitizedConfig: Object }}
   */
  static validate(rawConfig = {}) {
    const errors = [];
    const warnings = [];

    if (!rawConfig || typeof rawConfig !== 'object') {
      return {
        valid: false,
        errors: ['World configuration must be an object'],
        warnings: [],
        sanitizedConfig: null,
      };
    }

    // 1. World Name
    let name = typeof rawConfig.name === 'string' ? rawConfig.name.trim() : '';
    if (!name) {
      warnings.push('World name missing. Generated default name.');
      name = 'Autonomous Civilization Colony';
    } else if (name.length > 100) {
      name = name.slice(0, 100);
      warnings.push('World name truncated to 100 characters.');
    }

    // 2. Population Validation
    let population = Number(rawConfig.population);
    if (isNaN(population) || population <= 0) {
      errors.push('Population must be a valid positive integer.');
      population = this.RULES.POPULATION.default;
    } else if (population < this.RULES.POPULATION.min) {
      warnings.push(`Population ${population} below minimum threshold (${this.RULES.POPULATION.min}). Clamped to ${this.RULES.POPULATION.min}.`);
      population = this.RULES.POPULATION.min;
    } else if (population > this.RULES.POPULATION.max) {
      warnings.push(`Population ${population} exceeds maximum threshold (${this.RULES.POPULATION.max}). Clamped to ${this.RULES.POPULATION.max}.`);
      population = this.RULES.POPULATION.max;
    } else {
      population = Math.round(population);
    }

    // 3. Number of Cities
    let numberOfCities = Number(rawConfig.numberOfCities ?? rawConfig.cityCount);
    if (isNaN(numberOfCities) || numberOfCities <= 0) {
      warnings.push(`City count missing or invalid. Set to default ${this.RULES.CITIES_COUNT.default}.`);
      numberOfCities = this.RULES.CITIES_COUNT.default;
    } else if (numberOfCities < this.RULES.CITIES_COUNT.min) {
      numberOfCities = this.RULES.CITIES_COUNT.min;
    } else if (numberOfCities > this.RULES.CITIES_COUNT.max) {
      warnings.push(`City count clamped to ${this.RULES.CITIES_COUNT.max}.`);
      numberOfCities = this.RULES.CITIES_COUNT.max;
    } else {
      numberOfCities = Math.round(numberOfCities);
    }

    // 4. Biome & Geography
    let biome = typeof rawConfig.biome === 'string' ? rawConfig.biome.trim() : 'Desert';
    const matchedBiome = this.RULES.BIOMES.find((b) => b.toLowerCase() === biome.toLowerCase());
    if (matchedBiome) {
      biome = matchedBiome;
    }

    // 5. Government Type
    let governmentType = typeof rawConfig.governmentType === 'string' ? rawConfig.governmentType.trim() : 'Central Government';
    const matchedGov = this.RULES.GOVERNMENT_TYPES.find((g) => g.toLowerCase() === governmentType.toLowerCase());
    if (matchedGov) {
      governmentType = matchedGov;
    }

    // 6. Resources Validation
    const rawRes = rawConfig.resources || {};
    const sanitizedResources = {};
    for (const [resKey, defaultVal] of Object.entries(this.RULES.DEFAULT_RESOURCES)) {
      let val = Number(rawRes[resKey]);
      if (isNaN(val)) {
        val = defaultVal;
      } else if (val < this.RULES.RESOURCE_MIN) {
        warnings.push(`Resource ${resKey} cannot be negative; set to 0.`);
        val = 0;
      } else if (val > this.RULES.RESOURCE_MAX) {
        warnings.push(`Resource ${resKey} exceeds maximum cap; clamped to ${this.RULES.RESOURCE_MAX}.`);
        val = this.RULES.RESOURCE_MAX;
      }
      sanitizedResources[resKey] = Math.round(val);
    }

    // 7. Starting Capital & Economy
    let startingMoney = Number(rawConfig.startingMoney ?? rawConfig.startingCapital);
    if (isNaN(startingMoney) || startingMoney < this.RULES.STARTING_MONEY.min) {
      warnings.push(`Starting capital adjusted to minimum (${this.RULES.STARTING_MONEY.min} NC).`);
      startingMoney = this.RULES.STARTING_MONEY.default;
    } else if (startingMoney > this.RULES.STARTING_MONEY.max) {
      startingMoney = this.RULES.STARTING_MONEY.max;
    } else {
      startingMoney = Math.round(startingMoney);
    }

    // 8. Tax Rate
    let taxRate = Number(rawConfig.taxRate);
    if (isNaN(taxRate) || taxRate <= 0) {
      taxRate = this.RULES.TAX_RATE.default;
    } else if (taxRate > 1) {
      taxRate = taxRate / 100; // e.g. 15% -> 0.15
    }
    taxRate = Math.min(this.RULES.TAX_RATE.max, Math.max(this.RULES.TAX_RATE.min, Math.round(taxRate * 100) / 100));

    // 9. Industries & Public Services
    const industries = Array.isArray(rawConfig.industries) && rawConfig.industries.length > 0
      ? rawConfig.industries.map((s) => String(s).trim())
      : ['Agriculture & Food', 'Trade & Commerce', 'Healthcare & Hospitals'];

    const publicServices = Array.isArray(rawConfig.publicServices) && rawConfig.publicServices.length > 0
      ? rawConfig.publicServices.map((s) => String(s).trim())
      : ['Hospitals & Healthcare', 'Central Administration'];

    // 10. Cities Structure
    const cities = [];
    const baseCityName = name.replace(/civilization|colony|matrix/gi, '').trim() || 'Oasis';
    const capitalShare = numberOfCities === 1 ? 1.0 : 0.6;
    const secondaryShare = (1 - capitalShare) / (Math.max(1, numberOfCities - 1));

    for (let i = 0; i < numberOfCities; i++) {
      const isCapital = i === 0;
      const cityPop = isCapital
        ? Math.round(population * capitalShare)
        : Math.round(population * secondaryShare);

      cities.push({
        name: isCapital ? `${baseCityName} Prime (Capital)` : `${baseCityName} District 0${i + 1}`,
        population: cityPop,
        isCapital,
        coordinates: {
          x: isCapital ? 50 : 30 + (i * 25) % 40,
          y: isCapital ? 50 : 30 + (i * 30) % 40,
        },
        specialization: isCapital ? 'Central Government & Trade' : 'Agriculture & Water Extraction',
      });
    }

    const sanitizedConfig = {
      name,
      description: rawConfig.description || `A ${biome.toLowerCase()} civilization with ${population.toLocaleString()} citizens, ${numberOfCities} cities, governed under a ${governmentType}.`,
      population,
      numberOfCities,
      biome,
      governmentType,
      resources: sanitizedResources,
      startingMoney,
      taxRate,
      industries,
      publicServices,
      cities,
      simulationSpeed: Number(rawConfig.simulationSpeed) || 1.0,
      seed: Number(rawConfig.seed) || 83917492,
      rawPrompt: rawConfig.rawPrompt || '',
    };

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      sanitizedConfig,
    };
  }
}
